"use client"

import { X, MapPin, Clock, Users, Calendar, Tag, Building, Share2, Heart } from "lucide-react"
import { Button } from "@/components/ui/button"
import { Badge } from "@/components/ui/badge"
import type { Event } from "@/lib/events-data"
import { cn } from "@/lib/utils"

interface EventModalProps {
  event: Event | null
  onClose: () => void
}

export function EventModal({ event, onClose }: EventModalProps) {
  if (!event) return null

  const attendancePercent = Math.round((event.currentAttendees / event.maxAttendees) * 100)

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      {/* Backdrop */}
      <div className="absolute inset-0 bg-background/80 backdrop-blur-sm animate-in fade-in" onClick={onClose} />

      {/* Modal */}
      <div className="relative w-full max-w-3xl max-h-[90vh] overflow-auto bg-card border border-border rounded-2xl shadow-2xl animate-in zoom-in-95 fade-in">
        {/* Close Button */}
        <button
          onClick={onClose}
          className="absolute top-4 right-4 z-10 p-2 rounded-full bg-background/80 hover:bg-background text-foreground backdrop-blur-sm transition-colors"
        >
          <X className="w-5 h-5" />
        </button>

        {/* Image */}
        <div className="relative aspect-video">
          <img src={event.image || "/placeholder.svg"} alt={event.title} className="w-full h-full object-cover" />
          <div className="absolute inset-0 bg-gradient-to-t from-black/70 via-transparent to-transparent" />

          {/* Price Badge */}
          <Badge
            className={cn(
              "absolute top-4 left-4 text-sm px-3 py-1",
              event.isFree ? "bg-primary text-primary-foreground" : "bg-background/90 text-foreground backdrop-blur-sm",
            )}
          >
            {event.isFree ? "Бесплатно" : `${event.price.toLocaleString("ru-RU")} ₽`}
          </Badge>
        </div>

        {/* Content */}
        <div className="p-6 space-y-6">
          {/* Header */}
          <div className="space-y-2">
            <div className="flex items-start justify-between gap-4">
              <h2 className="text-2xl font-bold text-foreground">{event.title}</h2>
              <div className="flex gap-2">
                <Button variant="outline" size="icon" className="rounded-full bg-transparent">
                  <Heart className="w-4 h-4" />
                </Button>
                <Button variant="outline" size="icon" className="rounded-full bg-transparent">
                  <Share2 className="w-4 h-4" />
                </Button>
              </div>
            </div>
            <div className="flex flex-wrap gap-2">
              <Badge variant="secondary">{event.category}</Badge>
              {event.tags.map((tag) => (
                <Badge key={tag} variant="outline" className="text-muted-foreground">
                  <Tag className="w-3 h-3 mr-1" />
                  {tag}
                </Badge>
              ))}
            </div>
          </div>

          {/* Info Grid */}
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            <div className="flex items-center gap-3 p-3 rounded-lg bg-muted/50">
              <Calendar className="w-5 h-5 text-primary" />
              <div>
                <p className="text-xs text-muted-foreground">Дата</p>
                <p className="text-sm font-medium text-foreground">
                  {new Date(event.date).toLocaleDateString("ru-RU", {
                    day: "numeric",
                    month: "long",
                    year: "numeric",
                  })}
                </p>
              </div>
            </div>
            <div className="flex items-center gap-3 p-3 rounded-lg bg-muted/50">
              <Clock className="w-5 h-5 text-primary" />
              <div>
                <p className="text-xs text-muted-foreground">Время</p>
                <p className="text-sm font-medium text-foreground">{event.time}</p>
              </div>
            </div>
            <div className="flex items-center gap-3 p-3 rounded-lg bg-muted/50">
              <MapPin className="w-5 h-5 text-primary" />
              <div>
                <p className="text-xs text-muted-foreground">Место</p>
                <p className="text-sm font-medium text-foreground">{event.location}</p>
              </div>
            </div>
            <div className="flex items-center gap-3 p-3 rounded-lg bg-muted/50">
              <Users className="w-5 h-5 text-primary" />
              <div>
                <p className="text-xs text-muted-foreground">Участники</p>
                <p className="text-sm font-medium text-foreground">
                  {event.currentAttendees}/{event.maxAttendees}
                </p>
              </div>
            </div>
          </div>

          {/* Description */}
          <div className="space-y-2">
            <h3 className="font-semibold text-foreground">Описание</h3>
            <p className="text-muted-foreground leading-relaxed">{event.fullDescription}</p>
          </div>

          {/* Location Details */}
          <div className="flex items-start gap-3 p-4 rounded-lg bg-muted/50">
            <Building className="w-5 h-5 text-primary mt-0.5" />
            <div>
              <p className="font-medium text-foreground">{event.location}</p>
              <p className="text-sm text-muted-foreground">{event.address}</p>
              <p className="text-sm text-muted-foreground mt-1">Организатор: {event.organizer}</p>
            </div>
          </div>

          {/* Attendance Progress */}
          <div className="space-y-2">
            <div className="flex justify-between text-sm">
              <span className="text-muted-foreground">Заполненность</span>
              <span className="font-medium text-foreground">{attendancePercent}%</span>
            </div>
            <div className="h-2 bg-muted rounded-full overflow-hidden">
              <div
                className={cn(
                  "h-full rounded-full transition-all",
                  attendancePercent >= 90 ? "bg-destructive" : attendancePercent >= 70 ? "bg-chart-4" : "bg-primary",
                )}
                style={{ width: `${attendancePercent}%` }}
              />
            </div>
          </div>

          {/* Action Button */}
          <Button size="lg" className="w-full text-lg h-14">
            {event.isFree ? "Зарегистрироваться" : `Купить билет за ${event.price.toLocaleString("ru-RU")} ₽`}
          </Button>
        </div>
      </div>
    </div>
  )
}
